            // display in whichever language matches the UI — pPlanet handles both.
            dasha: pPlanet(dasha || ''),
            dashaAdjust: (dasha && (isEn ? ADDON_FOOD_DASHA_ADJUST_EN : ADDON_FOOD_DASHA_ADJUST)[dasha])
                || (isEn ? 'balanced for primary element' : 'สมดุลตามธาตุหลัก'),
