const _FC_SIGN_LORD_TH = ['อังคาร', 'ศุกร์', 'พุธ', 'จันทร์', 'อาทิตย์', 'พุธ', 'ศุกร์', 'อังคาร', 'พฤหัสบดี', 'เสาร์', 'เสาร์', 'พฤหัสบดี'];
